theta = linspace(0, 2*pi, 50);
r = linspace(0, 1, 50);
[R, Theta] = meshgrid(r, theta);

X = R .* cos(Theta);
Y = R .* sin(Theta);
f = 1 - 2.*X.^2 - 3.*Y.^2;
surf(X, Y, f) %[output:51a943ea]
colormap winter; %[output:51a943ea]
shading interp; %[output:51a943ea]
view(45, 30) %[output:51a943ea]

title('Grafiko f(x y) 3D vaizdavimas') %[output:51a943ea]
xlabel('x') %[output:51a943ea]
ylabel('y') %[output:51a943ea]
zlabel('z') %[output:51a943ea]

%%
clear
close all

x = linspace(-2, 2, 50);
y = linspace(-2, 2, 50);
[X, Y] = meshgrid(x, y);
f = sin(abs(X - Y)/20)*exp(-abs(X + Y));

surf(X, Y, f); %[output:8ef0ce6e]
colormap hot; %[output:8ef0ce6e]
shading interp; %[output:8ef0ce6e]
view(60, 30); %[output:8ef0ce6e]

title('Grafiko f(x y) 3D vaizdavimas') %[output:8ef0ce6e]
xlabel('x') %[output:8ef0ce6e]
ylabel('y') %[output:8ef0ce6e]
zlabel('z') %[output:8ef0ce6e]
%%
clear
close all

x = linspace(-2, 2);
y = linspace(-2, 2);
[X, Y] = meshgrid(x, y);
z = 1 - (X.^2 + Y.^2);
surf(X, Y, z) %[output:0e9cccf8]
colormap parula; %[output:0e9cccf8]
shading interp; %[output:0e9cccf8]
title('paviršius 1 (parula)'); %[output:0e9cccf8]
xlabel('x'); %[output:0e9cccf8]
ylabel('y'); %[output:0e9cccf8]
zlabel('z'); %[output:0e9cccf8]

surf(X, Y, z) %[output:5d6f2a91]
colormap cool; %[output:5d6f2a91]
shading interp; %[output:5d6f2a91]
title('paviršius 2 (cool)'); %[output:5d6f2a91]
xlabel('x'); %[output:5d6f2a91]
ylabel('y'); %[output:5d6f2a91]
zlabel('z'); %[output:5d6f2a91]

surf(X, Y, z) %[output:84ac15c1]
colormap nebula; %[output:84ac15c1]
shading interp; %[output:84ac15c1]
title('paviršius 3 (nebula)'); %[output:84ac15c1]
xlabel('x'); %[output:84ac15c1]
ylabel('y'); %[output:84ac15c1]
zlabel('z'); %[output:84ac15c1]


